<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { copy } from './input-preferences';
  interface Preferences {restore_session:boolean;restore_split_layouts:boolean;maximize_on_launch:boolean;split_screen_enabled:boolean;max_workspace_slots:number;transition_style:'slide'|'materialize'|'none';workspace_names:Record<string,string>;workspace_wallpapers:Record<string,string>}
  interface Snapshot {preferences:Preferences;defaults:Preferences}
  const switches=[['restore_session','Restore session','Restore applications to their previous workspaces after restart.'],['restore_split_layouts','Restore split layouts','Restore saved pane assignments and divider ratios after restart.'],['maximize_on_launch','Maximize app on launch','Open new application windows filling the work area.'],['split_screen_enabled','Enable split screen','Allow supported windows to share the work area in split layouts.']] as const;
  const ids=Array.from({length:9},(_,index)=>String(index+1));
  const hints=[['Switch to workspace 1','Alt+1'],['Move window to workspace 1','Alt+Shift+1'],['Show all workspaces','Alt+0'],['Split window left or right','Super+← / →'],['Split window top or bottom','Super+↑ / ↓']];
  let saved=$state<Preferences|null>(null),draft=$state<Preferences|null>(null),defaults=$state<Preferences|null>(null),busy=$state(false),loading=$state(true),error=$state(''),message=$state(''),resetPending=$state(false);
  let alive=true;
  let dirty=$derived(!!saved&&!!draft&&JSON.stringify(draft)!==JSON.stringify(saved));
  function accept(next:Snapshot){saved=copy(next.preferences);draft=copy(next.preferences);defaults=copy(next.defaults);resetPending=false;}
  async function reload(){busy=true;error='';message='';try{const next=await invoke<Snapshot>('get_workspaces');if(alive)accept(next);}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;loading=false;}}}
  function setEntry(key:'workspace_names'|'workspace_wallpapers',id:string,value:string){if(!draft)return;value=value.trim();if(value)draft[key][id]=value;else delete draft[key][id];}
  function discard(){if(saved&&defaults)accept({preferences:copy(saved),defaults:copy(defaults)});error='';message='';}
  function reset(){if(!draft||!defaults)return;const next=copy(defaults);for(const key of ['workspace_names','workspace_wallpapers'] as const){for(const [id,value] of Object.entries(draft[key]))if(!ids.includes(id))next[key][id]=value;}draft=next;resetPending=false;}
  async function browse(id:string){busy=true;error='';try{const path=await invoke<string|null>('pick_workspace_wallpaper');if(alive&&path)setEntry('workspace_wallpapers',id,path);}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  async function apply(){if(!saved||!draft||busy)return;busy=true;error='';message='';try{const next=await invoke<{snapshot:Snapshot;message:string}>('apply_workspaces',{change:{expected:copy(saved),requested:copy(draft)}});if(alive){accept(next.snapshot);message=next.message;}}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  onMount(()=>{void reload();return()=>{alive=false;};});
</script>
<div class="page-heading"><div><div class="eyebrow">ROOM FOR EVERY PART OF YOUR DAY</div><h1>Workspaces</h1><p>Organize your desktop, window behavior, and workspace backgrounds.</p></div><button class="quiet" disabled={busy} onclick={reload}>Reload workspaces</button></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}
{#if loading}<div class="loading" role="status">Reading workspace preferences…</div>{:else if draft}
<fieldset disabled={busy}><legend class="sr-only">Workspace preferences</legend>
<section class="section"><h2>Desktop behavior</h2><p class="description">Choose how workspaces appear, switch, and restore applications.</p><div class="settings-card"><div class="setting-row"><div><label for="workspace-slots">Visible workspace slots</label><p>Numbered buttons shown before overflow. This does not limit the number of workspaces.</p></div><input id="workspace-slots" type="number" min="1" max="9" step="1" bind:value={draft.max_workspace_slots} /></div><div class="setting-row"><div><label for="workspace-transition">Workspace transition</label><p>Desktop animations must also be enabled in Accessibility.</p></div><select id="workspace-transition" bind:value={draft.transition_style}><option value="slide">Slide</option><option value="materialize">Materialize</option><option value="none">None</option></select></div>{#each switches as [key,label,description]}<div class="setting-row"><div><label for={`workspace-${key}`}>{label}</label><p>{description}</p></div><input id={`workspace-${key}`} class="switch" type="checkbox" role="switch" bind:checked={draft[key]} /></div>{/each}</div></section>
<section class="section"><h2>Workspace names</h2><p class="description">Leave a name blank to use its default label.</p><div class="settings-card">{#each ids as id}<div class="setting-row"><label for={`workspace-name-${id}`}>Workspace {id}</label><input id={`workspace-name-${id}`} type="text" maxlength="128" placeholder={`Workspace ${id}`} value={draft.workspace_names[id]??''} onchange={event=>setEntry('workspace_names',id,event.currentTarget.value)} /></div>{/each}</div></section>
<section class="section"><h2>Workspace wallpapers</h2><p class="description">Use a local PNG, JPEG, WebP, or EXR image. Blank entries inherit the active theme wallpaper. Changes are saved only when you Apply.</p><div class="settings-card">{#each ids as id}<div class="setting-row"><label for={`workspace-wallpaper-${id}`}>Workspace {id}</label><div class="wallpaper-control"><input id={`workspace-wallpaper-${id}`} type="text" maxlength="4096" placeholder="Use theme wallpaper" value={draft.workspace_wallpapers[id]??''} onchange={event=>setEntry('workspace_wallpapers',id,event.currentTarget.value)} /><button class="quiet" aria-label={`Browse wallpaper for workspace ${id}`} onclick={()=>browse(id)}>Browse…</button></div></div>{/each}</div></section>
<section class="section"><h2>Default keyboard shortcuts</h2><p class="description">These are the built-in shortcuts. Review customized bindings in Keyboard.</p><div class="settings-card">{#each hints as [label,shortcut]}<div class="setting-row"><strong>{label}</strong><kbd>{shortcut}</kbd></div>{/each}</div></section>
<section class="section"><h2>Restore workspace defaults</h2><p class="description">Reset behavior and the first nine names and wallpapers in this draft. Saved split ratios are preserved.</p><button class="quiet" onclick={()=>resetPending=true}>Reset workspace settings</button>{#if resetPending}<div class="reset-prompt" role="group" aria-label="Confirm workspace reset"><p>Restore workspace defaults in this draft? Apply to save.</p><button class="quiet" onclick={()=>resetPending=false}>Keep workspace settings</button><button class="quiet" onclick={reset}>Reset workspace draft</button></div>{/if}</section>
</fieldset><footer class="apply-bar"><div><span class="status-dot" class:unsaved={dirty}></span>{dirty?'You have unapplied workspace changes':'Workspace preferences match the saved configuration'}</div><div class="apply-actions"><button class="quiet" disabled={busy||!dirty} onclick={discard}>Discard workspace changes</button><button class="primary" disabled={busy||!dirty} onclick={apply}>Apply workspace changes</button></div></footer>
{/if}
<style>fieldset{padding:0;margin:0;border:0;min-width:0}.description{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:12px 0 18px}input:not([type=checkbox]),select{font:inherit;font-size:12px;border:1px solid var(--fd-border);border-radius:8px;padding:10px;background:var(--fd-surface);color:var(--fd-text);width:45%;max-width:340px}input[type=number]{width:80px}.wallpaper-control{display:flex;gap:8px;width:55%;align-items:center}.wallpaper-control input{flex:1;min-width:0;max-width:none}.setting-row>div{min-width:0}strong{font-size:12px}kbd{font:11px ui-monospace,monospace;color:var(--fd-text-muted);white-space:nowrap}.reset-prompt{padding:20px;border:1px solid var(--fd-border);border-radius:var(--fd-radius);margin-top:18px}.reset-prompt p{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin-bottom:12px}.reset-prompt button{margin-right:8px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:600px){input:not([type=checkbox]),select,.wallpaper-control{width:100%;max-width:none}}</style>
